const repo = $env.GITHUB_REPO || '';
const githubToken = $env.GITHUB_TOKEN || '';
const anthropicApiKey = $env.ANTHROPIC_API_KEY || '';
const discordWebhookUrl = $env.DISCORD_WEBHOOK_URL || '';
const [owner, name] = repo.split('/');
if (!owner || !name) {
  throw new Error('Set GITHUB_REPO as owner/repo');
}
if (!githubToken) {
  throw new Error('Set GITHUB_TOKEN for GitHub API access');
}
if (!anthropicApiKey) {
  throw new Error('Set ANTHROPIC_API_KEY for Claude summary generation');
}
if (!discordWebhookUrl) {
  throw new Error('Set DISCORD_WEBHOOK_URL for summary delivery');
}
const language = ($env.SUMMARY_LANGUAGE || 'EN').toUpperCase() === 'FR' ? 'FR' : 'EN';
const until = new Date();
const since = new Date(until.getTime() - 7 * 24 * 60 * 60 * 1000);
return [{
  json: {
    githubRepo: repo,
    owner,
    repo: name,
    sinceIso: since.toISOString(),
    untilIso: until.toISOString(),
    language,
    githubToken,
    anthropicApiKey,
    discordWebhookUrl
  }
}];

const config = $json;
const headers = {
  Accept: 'application/vnd.github+json',
  Authorization: `Bearer ${config.githubToken}`,
  'X-GitHub-Api-Version': '2022-11-28'
};
async function githubJson(path) {
  const response = await fetch(`https://api.github.com${path}`, { headers });
  if (!response.ok) {
    const body = await response.text();
    throw new Error(`GitHub API ${path} failed with ${response.status}: ${body.slice(0, 500)}`);
  }
  return response.json();
}
const sinceDate = config.sinceIso.slice(0, 10);
const untilDate = config.untilIso.slice(0, 10);
const repoPath = `${config.owner}/${config.repo}`;
const commits = await githubJson(`/repos/${repoPath}/commits?since=${encodeURIComponent(config.sinceIso)}&until=${encodeURIComponent(config.untilIso)}&per_page=100`);
const issueQuery = encodeURIComponent(`repo:${repoPath} is:issue is:closed closed:${sinceDate}..${untilDate}`);
const prQuery = encodeURIComponent(`repo:${repoPath} is:pr is:merged merged:${sinceDate}..${untilDate}`);
const closedIssuePayload = await githubJson(`/search/issues?q=${issueQuery}&per_page=100`);
const mergedPrPayload = await githubJson(`/search/issues?q=${prQuery}&per_page=100`);
const compactCommits = (commits || []).slice(0, 40).map((commit) => ({
  sha: (commit.sha || '').slice(0, 7),
  author: commit.commit?.author?.name || commit.author?.login || 'unknown',
  message: (commit.commit?.message || '').split('\n')[0]
}));
const compactIssues = (closedIssuePayload.items || []).slice(0, 40).map((issue) => ({
  number: issue.number,
  title: issue.title,
  closedAt: issue.closed_at,
  url: issue.html_url
}));
const compactPrs = (mergedPrPayload.items || []).slice(0, 40).map((pr) => ({
  number: pr.number,
  title: pr.title,
  mergedAt: pr.closed_at,
  author: pr.user?.login || 'unknown',
  url: pr.html_url
}));
return [{
  json: {
    ...config,
    counts: {
      commits: commits.length,
      closedIssues: closedIssuePayload.total_count || compactIssues.length,
      mergedPrs: mergedPrPayload.total_count || compactPrs.length
    },
    commits: compactCommits,
    closedIssues: compactIssues,
    mergedPrs: compactPrs
  }
}];

const instruction = $json.language === 'FR'
  ? 'Write the narrative summary in French.'
  : 'Write the narrative summary in English.';
const prompt = `${instruction}\n\nCreate a concise weekly engineering narrative for ${$json.githubRepo}. Include sections: Overview, Highlights, Merged PRs, Closed Issues, Risks or Follow-ups. Be specific, cite issue and PR numbers when available, and do not invent work.\n\nWindow: ${$json.sinceIso} to ${$json.untilIso}\n\nCounts:\n${JSON.stringify($json.counts, null, 2)}\n\nCommits:\n${JSON.stringify($json.commits, null, 2)}\n\nClosed issues:\n${JSON.stringify($json.closedIssues, null, 2)}\n\nMerged PRs:\n${JSON.stringify($json.mergedPrs, null, 2)}`;
return [{
  json: {
    ...$json,
    claudeRequest: {
      model: 'claude-sonnet-4-20250514',
      max_tokens: 1200,
      messages: [
        {
          role: 'user',
          content: prompt
        }
      ]
    }
  }
}];

const config = $('Build Claude Request').first().json;
const response = $json;
const text = response.content?.map((part) => part.text || '').join('\n').trim() || 'Claude returned an empty summary.';
return [{
  json: {
    discordWebhookUrl: config.discordWebhookUrl,
    content: `## Weekly summary for ${config.githubRepo}\n\n${text}`
  }
}];
